/**
 * Sorts elements in the list in-place according to their natural sort order.
 *
 * The sort is _stable_. It means that equal elements preserve their order relative to each other after sorting.
 *
 * @sample samples.collections.Collections.Sorting.sortMutableList
 */
public actual fun <T : Comparable<T>> MutableList<T>.sort(): Unit = sortWith(naturalOrder())

/**
 * Sorts elements in the list in-place according to the order specified with [comparator].
 *
 * The sort is _stable_. It means that equal elements preserve their order relative to each other after sorting.
 *
 * @sample samples.collections.Collections.Sorting.sortMutableListWith
 */
public actual fun <T> MutableList<T>.sortWith(comparator: Comparator<in T>): Unit {
    if (size > 1) {
        val it = listIterator()
        @Suppress("UNCHECKED_CAST")
        val erasedComparator = comparator as Comparator<in Any?>
        val sortedArray = toTypedArray<Any?>().apply { sortWith(erasedComparator) }
        for (v in sortedArray) {
            val _ = it.next()
            it.set(@Suppress("UNCHECKED_CAST") (v as T))
        }
    }
}

private external fun dotNetErasedArrayOfNulls(reference: Array<*>, size: Int): Array<*>

private external fun dotNetErasedArraySet(array: Array<*>, index: Int, value: Any?)

private fun mergeSortErased(array: Array<*>, start: Int, endInclusive: Int, comparator: Comparator<in Any?>) {
    val buffer = dotNetErasedArrayOfNulls(array, array.size)
    val result = mergeSortErased(array, buffer, start, endInclusive, comparator)
    if (result !== array) {
        for (i in start..endInclusive) dotNetErasedArraySet(array, i, result[i])
    }
}

private fun mergeSortErased(array: Array<*>, buffer: Array<*>, start: Int, end: Int, comparator: Comparator<in Any?>): Array<*> {
    if (start == end) {
        return array
    }

    val median = (start + end) / 2
    val left = mergeSortErased(array, buffer, start, median, comparator)
    val right = mergeSortErased(array, buffer, median + 1, end, comparator)

    val target = if (left === buffer) array else buffer

    // Merge.
    var leftIndex = start
    var rightIndex = median + 1
    for (i in start..end) {
        when {
            leftIndex <= median && rightIndex <= end -> {
                val leftValue = left[leftIndex]
                val rightValue = right[rightIndex]

                if (comparator.compare(leftValue, rightValue) <= 0) {
                    dotNetErasedArraySet(target, i, leftValue)
                    leftIndex++
                } else {
                    dotNetErasedArraySet(target, i, rightValue)
                    rightIndex++
                }
            }
            leftIndex <= median -> {
                dotNetErasedArraySet(target, i, left[leftIndex])
                leftIndex++
            }
            else /* rightIndex <= end */ -> {
                dotNetErasedArraySet(target, i, right[rightIndex])
                rightIndex++
            }
        }
    }

    return target
}

internal fun <T> sortArrayWith(array: Array<out T>, fromIndex: Int, toIndex: Int, comparator: Comparator<in T>) {
    if (fromIndex < toIndex - 1) {
        @Suppress("UNCHECKED_CAST")
        mergeSortErased(array, fromIndex, toIndex - 1, comparator as Comparator<in Any?>)
    }
}

internal fun <T: Comparable<T>> sortArray(array: Array<out T>, fromIndex: Int, toIndex: Int) {
    if (fromIndex < toIndex - 1) {
        @Suppress("UNCHECKED_CAST")
        mergeSortErased(array, fromIndex, toIndex - 1, naturalOrder<T>() as Comparator<in Any?>)
    }
}

// ByteArray    =============================================================================
private fun partition(
        array: ByteArray, left: Int, right: Int): Int {
    var i = left
    var j = right
    val pivot = array[(left + right) / 2]
    while (i <= j) {
        while (array[i] < pivot)
            i++
        while (array[j] > pivot)
            j--
        if (i <= j) {
            val tmp = array[i]
            array[i] = array[j]
            array[j] = tmp
            i++
            j--
        }
    }
    return i
}

private fun quickSort(
        array: ByteArray, left: Int, right: Int) {
    val index = partition(array, left, right)
    if (left < index - 1)
        quickSort(array, left, index - 1)
    if (index < right)
        quickSort(array, index, right)
}

